def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    aggressive_count = 0
    desperate_count = 0
    cindy_like_present = False

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                bid = float(bid)
                prev_bids.append(bid)
                if bid >= 120:
                    aggressive_count += 1
                if bid >= 100:
                    cindy_like_present = True
            if int(opp.get('no_water_days', 0)) >= 2 or float(opp.get('hp', 10)) <= 2:
                desperate_count += 1

    if not alive_opps:
        return min(budget, 20.0)

    tight_supply = supply <= 17.0
    ample_supply = supply >= 22.0

    if prev_bids:
        highest_prev = max(prev_bids)
        second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else 0.0
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 0.0
        second_prev = 0.0
        avg_prev = 0.0

    urgency = 0
    if hp <= 2 or no_water >= 2:
        urgency = 3
    elif hp <= 4 or no_water >= 1:
        urgency = 2
    elif hp <= 6:
        urgency = 1

    if urgency == 3:
        bid = max(95.0, highest_prev + 3.0)
        if cindy_like_present:
            bid = max(bid, 118.0)
    elif urgency == 2:
        if tight_supply:
            bid = max(62.0, second_prev + 2.0, avg_prev * 0.9)
        else:
            bid = max(48.0, second_prev + 1.5, avg_prev * 0.75)
    elif urgency == 1:
        if aggressive_count > 0 and not tight_supply:
            bid = 18.0
        else:
            bid = max(28.0, min(55.0, second_prev + 1.0))
    else:
        if aggressive_count > 0:
            bid = 10.0 if ample_supply else 14.0
        elif desperate_count >= 2 and tight_supply:
            bid = 36.0
        else:
            bid = 20.0 if ample_supply else 26.0

    if day >= 8 and hp > 4 and budget < 180:
        bid *= 0.85
    if day >= 8 and urgency >= 2:
        bid *= 1.1

    reserve_floor = 0.0
    if day <= 3:
        reserve_floor = 280.0
    elif day <= 6:
        reserve_floor = 180.0
    else:
        reserve_floor = 80.0

    max_affordable = budget
    if budget > reserve_floor:
        max_affordable = max(0.0, budget - reserve_floor + DAILY_SALARY * 0.35)

    if urgency == 3:
        max_affordable = budget
    elif urgency == 2:
        max_affordable = min(budget, max(max_affordable, budget * 0.6))

    bid = min(bid, max_affordable, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0)
    day = day_context.get('day', 0)

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0)
    no_water_days = my_status.get('no_water_days', 0)

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids for immediate reaction
    yesterday_bids = []
    yesterday_pressures = []
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass
        # Use remaining hp as a proxy for their urgency yesterday
        prev_hp_after = prev.get('hp_after', None)
        if prev_hp_after is not None:
            try:
                yesterday_pressures.append((float(prev_hp_after), opp_id))
            except Exception:
                pass

    # Determine aggressiveness threshold from yesterday
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        median_prev_bid = sorted(yesterday_bids)[len(yesterday_bids)//2]
    else:
        highest_prev_bid = 0.0
        median_prev_bid = 0.0

    # Estimate how many water units are likely needed/available
    # supply is between 15 and 25; our requirement is 9.
    # If supply is closer to 15, water is scarce -> bid more.
    scarcity = 0.0
    try:
        scarcity = (MAX_SUPPLY - float(supply)) / float(MAX_SUPPLY - MIN_SUPPLY)
    except Exception:
        scarcity = 0.5
    scarcity = max(0.0, min(1.0, scarcity))

    # Urgency from our own state
    urgency = 0.0
    if hp <= 2:
        urgency = 1.0
    elif hp <= 4:
        urgency = 0.7
    elif hp <= 6:
        urgency = 0.45
    else:
        urgency = 0.25

    if no_water_days >= 2:
        urgency = max(urgency, 0.8)

    # Decide target bid:
    # - If Cindy survived with high bid yesterday, we may need to match/just exceed the high cluster.
    # - Otherwise, bid around median+small premium.
    premium = 2.0 + 6.0 * scarcity

    # If someone previously bid very high, we counter with a near-top bid but cap by our budget.
    if highest_prev_bid >= DAILY_SALARY * 1.3:  # ~117+ 
        # Match just above the highest_prev_bid scaled by urgency.
        target = highest_prev_bid + premium
        # If we are healthy, avoid overpaying.
        if urgency < 0.5:
            target = min(target, median_prev_bid + premium + 10.0)
    else:
        # Bid around median with premium scaled by scarcity/urgency
        target = median_prev_bid + premium * (0.8 + 0.6 * urgency)

    # Convert target into a safe spend cap based on our budget and urgency
    # Keep some budget for later days.
    budget_cap = budget
    if hp <= 3:
        budget_cap = min(budget_cap, DAILY_SALARY * 0.95)
    elif hp <= 6:
        budget_cap = min(budget_cap, DAILY_SALARY * 0.75)
    else:
        budget_cap = min(budget_cap, DAILY_SALARY * 0.6)

    bid = min(budget_cap, target)

    # Ensure non-negative and at least a minimal competitive bid when urgency is high
    if bid < 0:
        bid = 0.0

    # Minimal floor to avoid losing when others likely bid aggressively
    min_floor = 15.0 + 40.0 * (0.6 * scarcity + 0.4 * urgency)
    if urgency >= 0.7:
        bid = max(bid, min_floor)

    # Hard cap: cannot exceed budget
    bid = min(bid, budget)

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Gather yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        # fallback: bid proportional to desperation
        if hp <= 2 or no_water_days > 1:
            return min(budget, DAILY_SALARY * 0.9)
        else:
            return min(budget, DAILY_SALARY * 0.6)

    avg_opponent_bid = sum(yesterday_bids) / len(yesterday_bids)

    # Determine target bid based on desperation
    if hp <= 2 or no_water_days >= 1:
        # Need water urgently: bid just above average to ensure win
        target = avg_opponent_bid + 1.0
        # cap at budget and salary
        target = min(budget, target)
        return max(target, 1.0)
    elif hp <= 4:
        # Moderate need: slightly above average
        target = avg_opponent_bid + 0.5
        target = min(budget, target)
        return max(target, 1.0)
    else:
        # Healthy: save money, bid conservatively
        target = avg_opponent_bid * 0.8
        target = min(budget, target)
        return max(target, 1.0)
